Given the head of a doubly-linked list, a position p, and an integer x. Insert a new node with value x at the position just after pth node (0-based indexing) in the doubly linked list and return the head of the modified list.Examples:Input: p = 2, x = 6 Output: 2 <-> 4 <-> 5 <-> 6Explanation: Insert a node of value 6 after the 2nd node. Input: p = 0, x = 44  Output: 1 <-> 44 <-> 2 <-> 3 <-> 4Explanation: Insert a node of value 44 after the 0th node. Try It YourselfTable of Content[Naive Approach] Using Auxiliary Array - O(n) Time and O(n) Space[Expected Approach] Single Traversal - O(n) Time and O(1) Space[Naive Approach] Using Auxiliary Array - O(n) Time and O(n) SpaceThe idea is to first store all the nodes of the doubly linked list in an array. This allows direct access to the p-th node, after which the new node is inserted by updating the required next and prev pointers.Working of Approach:Traverse the list and store each node in an array.Access the p-th node directly from the array.Create a new node with value x.Update the next and prev pointers to insert the new node.Return the head of the modified list.
            C++

    #include <iostream>
#include <vector>
using namespace std;

class Node
{
  public:
    int data;
    Node *next;
    Node *prev;

    Node(int x)
    {
        data = x;
        next = prev = nullptr;
    }
};

Node *insertAtPos(Node *head, int p, int x)
{

    // Store all nodes in an array
    vector<Node *> nodes;
    Node *curr = head;

    while (curr)
    {
        nodes.push_back(curr);
        curr = curr->next;
    }

    // Create new node
    Node *newNode = new Node(x);

    // Get p-th node
    Node *pNode = nodes[p];

    // Insert new node
    newNode->next = pNode->next;
    newNode->prev = pNode;

    if (pNode->next)
        pNode->next->prev = newNode;

    pNode->next = newNode;

    return head;
}

// Function to print the doubly linked list
void printList(Node *head)
{
    while (head)
    {
        cout << head->data;
        if (head->next)
            cout << " <-> ";
        head = head->next;
    }
    cout << endl;
}

int main()
{

    // Creating linked list: 2 <-> 4 <-> 5
    Node *head = new Node(2);
    head->next = new Node(4);
    head->next->prev = head;
    head->next->next = new Node(5);
    head->next->next->prev = head->next;

    int p = 2, x = 6;

    head = insertAtPos(head, p, x);

    printList(head);

    return 0;
}


